  separate(corner_1_koordinate, c("c_1_x","c_1_y"), sep = ",", convert = TRUE) %>% 
  separate(corner_2_koordinate, c("c_2_x","c_2_y"), sep = ",", convert = TRUE) %>% 
  separate(motiv_koordinate, c("m_x","m_y"), sep = ",", convert = TRUE) 


