  mutate(user_name = str_extract(jpg_name, ".+(?=_\\d+_\\d+_\\d+_n_)")) %>% 
  left_join(df_mapping_acc_raw %>% 
              select(user_name = User.Name, art = Art, sub_art = Sub_Art),
            by = "user_name") %>% 
  filter(!art %in% c("Lokal", "OUT", NA))


